const item = $input.item.json;
const rawError = item && item.error;
const rawMessage = typeof rawError === 'string'
  ? rawError
  : (rawError && rawError.message) ? rawError.message : 'Unbekannter Fehler';

return [{
  json: {
    ...item,
    errorMessage: 'Bei der Kommunikation mit dem lokalen Ollama-Modell ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.\n\nDetails: ' + rawMessage
  }
}];

const item = $input.item.json;

// Wird nur erreicht, wenn teamPerformance.dataAvailable === false (Gate
// "Teamdiagnose: Datenverfuegbarkeit pruefen" davor). Es gibt in diesem Fall
// nichts, was ein LLM interpretieren koennte - die Ollama-Chain wird bewusst
// NICHT aufgerufen, das Fehlen der Datengrundlage wird stattdessen selbst zum
// (weiterhin schema-gueltigen) Ergebnis. Siehe n8n/README.md.
const teamDiagnosis = {
  simulated: false,
  dataAvailable: false,
  diagnosisCategory: 'no_data',
  evidence: [
    `Keine importierten Analytics-Daten fuer '${item.club}' vorhanden (Data Table 'football_scouting_raw') - es werden keine Ersatzwerte erfunden.`
  ],
  leagueComparisonAvailable: false,
  leagueComparison: `Ohne Datengrundlage ist kein Ligavergleich fuer '${item.club}' moeglich.`,
  hypotheses: [
    'Ohne Datengrundlage kann keine belastbare Hypothese zur sportlichen Situation abgeleitet werden.'
  ],
  counterHypotheses: [],
  mainProblem: `Fuer '${item.club}' liegen keine CSV-Analytics-Daten vor; auf dieser Datengrundlage ist keine Diagnose moeglich.`,
  uncertainties: [
    'Diese Aussage stammt aus dem CSV-Analytics-Adapter (Data Table football_scouting_raw), nicht aus einer echten Qlik-Analyse oder Websuche.',
    'Ohne Datengrundlage konnte kein LLM zur Interpretation herangezogen werden.'
  ]
};

return [{ json: { ...item, teamDiagnosis } }];

const item = $input.item.json;
const perf = item.teamPerformance;
const matches = item.teamMatches;

// Bereitet die vom LLM zu interpretierenden GEGEBENEN FAKTEN vor: dieselbe
// deterministische Faktenextraktion aus teamPerformance/teamMatches wie zuvor
// (CSV-Analytics-Adapter, siehe n8n/README.md), aber OHNE die Interpretation
// (Hypothesen, Hauptproblem, Ligavergleich, Gegenhypothesen) - die uebernimmt
// jetzt "Teamdiagnose LLM". Diese Trennung stellt sicher, dass die Evidenz
// ausschliesslich aus echten Kennzahlen besteht (nichts erfunden) und das LLM
// erkennbar nur interpretiert statt selbst Zahlen zu erzeugen.
const recentResults = (matches && Array.isArray(matches.matches))
  ? matches.matches.map((m) => `${m.result} ${m.goalsFor}:${m.goalsAgainst} vs. ${m.opponent} (${m.date})`)
  : [];

const teamDiagnosisEvidence = [
  `Bilanz der letzten ${perf.matchesAnalyzed} Pflichtspiele: ${perf.wins}S/${perf.draws}U/${perf.losses}N, Tore ${perf.goalsFor}:${perf.goalsAgainst}, Punkte ${perf.points} (CSV-Analytics-Adapter, Data Table football_scouting_raw).`,
  `Form (neuestes Spiel zuerst): ${perf.form.join('-')}.`,
  `Punkteschnitt der letzten ${perf.matchesAnalyzed} Spiele: ${(perf.points / perf.matchesAnalyzed).toFixed(2)} pro Spiel.`,
  `Durchschnittliche Tore pro Spiel: ${perf.avgGoalsFor} erzielt, ${perf.avgGoalsAgainst} kassiert (Tordifferenz ${perf.goalDifference}).`,
  ...recentResults
];

return [{ json: { ...item, teamDiagnosisEvidence } }];

parameters.text:
=Verein: {{ $json.club }}
Zielsetzung des Auftrags: {{ $json.objective }}
Zusaetzlicher Kontext: {{ $json.additionalContext || '(keiner)' }}

Gegebene Fakten aus dem CSV-Analytics-Adapter (bereits real berechnet - NICHT erfinden, nur interpretieren):
{{ $json.teamDiagnosisEvidence.join('\n') }}

Rohkennzahlen: avgGoalsFor={{ $json.teamPerformance.avgGoalsFor }}, avgGoalsAgainst={{ $json.teamPerformance.avgGoalsAgainst }}, Punkte={{ $json.teamPerformance.points }} aus {{ $json.teamPerformance.matchesAnalyzed }} Spielen.

Interpretiere ausschliesslich auf Basis dieser Fakten (keine erfundenen Zahlen, keine externen Annahmen). Ordne die Lage genau einer von drei Kategorien zu: 'defensive' (mehr Gegentore als eigene Tore / auffaellige Anfaelligkeit), 'offensive' (zu wenige eigene Tore trotz stabilerer Defensive) oder 'neutral' (kein eindeutiger struktureller Schwerpunkt). Liefere zusaetzlich einen Ligavergleich: Dir liegen ausschliesslich die Kennzahlen von '{{ $json.club }}' vor, KEINE Liga-Durchschnittswerte und KEINE Kennzahlen anderer Bundesliga-Vereine. Erfinde deshalb KEINE Platzierung, KEINEN Liga-Durchschnitt und KEINEN Vergleich zu konkreten anderen Vereinen - benenne in 'leagueComparison' stattdessen explizit, dass auf dieser Datengrundlage kein belastbarer Vergleich zur Bundesliga-Konkurrenz moeglich ist, und was dafuer zusaetzlich vorliegen muesste (z. B. Liga-weite Kennzahlen aller Vereine). Liefere ausserdem Hypothesen zur Ursache, Gegenhypothesen (plausible alternative Erklaerungen, die denselben Fakten ebenfalls nicht widersprechen), das Hauptproblem in einem Satz sowie Unsicherheiten (was diese Diagnose NICHT abdeckt, z. B. fehlende erwartbare Tore/xG, Gegnerstaerke, Verletzungen, kein Kontext zu anderen Vereinen).

parameters.jsCode:
// n8n 2.35.7 (ChainLlm.node.ts v1.6 mit aktivem Output Parser) setzt
// shouldUnwrapObjects = true: responseFormatter.ts liefert die geparsten
// Structured-Output-Felder deshalb direkt als Node-JSON zurueck, NICHT unter
// einer zusaetzlichen "output"-Huelle. $input.item.json IST bereits das
// geparste Objekt (z. B. $json.diagnosisCategory), nicht
// $input.item.json.output. $('Teamdiagnose: Evidenz aufbereiten') liefert
// das vollstaendige Item von direkt vor dem Chain-Aufruf zurueck (n8n haelt
// den Output bereits gelaufener Nodes fuer die Dauer der Execution vor) -
// siehe n8n/README.md.
const parsed = $input.item.json;
const original = $('Teamdiagnose: Evidenz aufbereiten').first().json;

// Ob eine belastbare Liga-Vergleichsgrundlage vorliegt, ist ein
// deterministisches Faktum dieses Workflows (dem LLM werden ausschliesslich
// die Kennzahlen des einen betrachteten Vereins uebergeben, siehe
// 'Teamdiagnose LLM') und wird deshalb HIER gesetzt statt vom LLM erfragt zu
// werden - eine Promptvorgabe allein kann ein halluziniertes leagueComparison
// nicht zuverlaessig verhindern (siehe Review). Sobald eine echte
// Liga-weite Datenquelle angebunden wird, muss diese Konstante durch die
// tatsaechliche Verfuegbarkeitspruefung ersetzt werden.
const leagueComparisonAvailable = false;

const teamDiagnosis = {
  simulated: false,
  dataAvailable: true,
  diagnosisCategory: parsed.diagnosisCategory,
  // evidence bleibt der deterministisch berechnete Befund, NICHT die
  // LLM-Ausgabe - Befund und Interpretation bleiben so getrennt.
  evidence: original.teamDiagnosisEvidence,
  leagueComparisonAvailable,
  // Ohne Vergleichsgrundlage wird die LLM-Ausgabe fuer leagueComparison
  // verworfen und durch einen festen, wahrheitsgemaessen Hinweis ersetzt -
  // so kann ein nicht regelkonformes LLM keine erfundene Bundesliga-
  // Platzierung/-Durchschnitt mehr bis zur Empfehlung durchreichen.
  leagueComparison: leagueComparisonAvailable
    ? parsed.leagueComparison
    : `Auf dieser Datengrundlage liegt kein belastbarer Vergleich zur Bundesliga-Konkurrenz vor: es liegen ausschliesslich Kennzahlen von '${original.club}' vor, keine Liga-Durchschnittswerte oder Kennzahlen anderer Vereine.`,
  hypotheses: parsed.hypotheses,
  counterHypotheses: parsed.counterHypotheses,
  mainProblem: parsed.mainProblem,
  uncertainties: parsed.uncertainties
};

return [{ json: { ...original, teamDiagnosis } }];

const item = $input.item.json;
const d = item.teamDiagnosis;
const errors = [];

if (!d || typeof d !== 'object') {
  errors.push('teamDiagnosis fehlt oder ist kein Objekt.');
} else {
  if (!Array.isArray(d.evidence) || d.evidence.length === 0) errors.push('teamDiagnosis.evidence fehlt oder ist leer.');
  if (typeof d.leagueComparisonAvailable !== 'boolean') errors.push('teamDiagnosis.leagueComparisonAvailable fehlt oder ist kein boolean.');
  if (typeof d.leagueComparison !== 'string' || !d.leagueComparison.trim()) errors.push('teamDiagnosis.leagueComparison fehlt.');
  if (!Array.isArray(d.hypotheses) || d.hypotheses.length === 0) errors.push('teamDiagnosis.hypotheses fehlt oder ist leer.');
  if (!Array.isArray(d.counterHypotheses)) errors.push('teamDiagnosis.counterHypotheses fehlt oder ist kein Array.');
  if (typeof d.mainProblem !== 'string' || !d.mainProblem.trim()) errors.push('teamDiagnosis.mainProblem fehlt.');
  if (!Array.isArray(d.uncertainties)) errors.push('teamDiagnosis.uncertainties fehlt oder ist kein Array.');
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Teamdiagnose ist ungueltig und wird nicht als fachliche Grundlage verwendet.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;

// Grenzt den Positionspool generisch anhand der (jetzt LLM-erzeugten)
// teamDiagnosis.diagnosisCategory ein - kein Sonderfall fuer einen bestimmten
// Verein oder eine bestimmte Position (siehe n8n/README.md). "Spielerprofil
// LLM" bekommt diesen Pool als verbindliche Vorgabe im Prompt; "Spielerprofil
// pruefen" prueft zusaetzlich deterministisch, dass die vom LLM gewaehlte
// Position tatsaechlich darin vorkommt (die Parser-Schema-Validierung allein
// kann das nicht garantieren, da 'position' dort nur als String typisiert ist).
const DEFENSIVE_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld'];
const ATTACKING_POSITIONS = ['Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];
const ALL_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld', 'Zentrales Mittelfeld', 'Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];

const diagnosisCategory = (item.teamDiagnosis && item.teamDiagnosis.diagnosisCategory) || 'no_data';
const allowedPositions = diagnosisCategory === 'defensive'
  ? DEFENSIVE_POSITIONS
  : diagnosisCategory === 'offensive'
    ? ATTACKING_POSITIONS
    : ALL_POSITIONS;

return [{ json: { ...item, allowedPositions } }];

