Zielsetzung des Auftrags: {{ $json.objective }}
Zusaetzlicher Kontext: {{ $json.additionalContext || '(keiner)' }}

Teamdiagnose (bereits erstellt):
Hauptproblem: {{ $json.teamDiagnosis.mainProblem }}
Diagnosekategorie: {{ $json.teamDiagnosis.diagnosisCategory }}
Hypothesen: {{ $json.teamDiagnosis.hypotheses.join('; ') }}
Gegenhypothesen: {{ $json.teamDiagnosis.counterHypotheses.join('; ') || '(keine)' }}
Ligavergleich: {{ $json.teamDiagnosis.leagueComparison }}
Unsicherheiten: {{ $json.teamDiagnosis.uncertainties.join('; ') }}

Erlaubter Positionspool fuer diese Diagnose - waehle 'position' AUSSCHLIESSLICH aus dieser Liste, keine andere Position: {{ $json.allowedPositions.join(', ') }}

Leite aus der Teamdiagnose ein strukturiertes Anforderungsprofil fuer die Spielersuche ab: die gesuchte 'position' (nur aus obiger Liste), eine kurze taktische 'role'-Beschreibung, 'weightedCriteria' (Gewichtung jeweils zwischen 0 und 1) ausschliesslich mit den Kriteriennamen goals, assists, rating, appearances, age, minutesPlayed, marketValueMEUR, 'constraints' als Liste strukturierter Objekte { field: 'age'|'marketValueMEUR', operator: 'max'|'min', value: Zahl } - NUR wenn ein konkreter Alters- oder Budget-/Marktwertrahmen aus dem zusaetzlichen Kontext ableitbar ist (z. B. ein explizites Alterslimit oder eine Marktwert-/Budgetobergrenze in Mio. EUR); ist kein konkreter Zahlenwert ableitbar, liefere ein leeres Array statt einen erfundenen Rahmen und eine 'reasoning', die sich explizit auf das Hauptproblem der Teamdiagnose bezieht.

{{ $json.reviewFeedback ? ('Rueckmeldung eines menschlichen Reviewers zu einer vorherigen Fassung dieses Profils (Request Changes) - ueberarbeite Rolle, Kriterien, Constraints und/oder Begruendung entsprechend, ohne den erlaubten Positionspool oder die zulaessigen Kriteriennamen zu verletzen:\n' + $json.reviewFeedback) : '' }}

parameters.jsCode:
// n8n 2.35.7 (ChainLlm.node.ts v1.6 mit aktivem Output Parser) setzt
// shouldUnwrapObjects = true: die geparsten Structured-Output-Felder liegen
// deshalb direkt auf $input.item.json, nicht unter $input.item.json.output.
// $('Spielerprofil: Positionspool ermitteln').first() liefert das erste Item
// dieses Vor-LLM-Nodes ohne pairedItem-Abhaengigkeit (gleicher Grund wie bei
// 'Teamdiagnose zusammenfuehren': die Basic LLM Chain liefert auf dem
// Erfolgspfad kein pairedItem, '.item' wuerde hier werfen). Siehe
// n8n/README.md.
const parsed = $input.item.json;
const original = $('Spielerprofil: Positionspool ermitteln').first().json;

const playerProfile = {
  simulated: false,
  position: parsed.position,
  role: parsed.role,
  weightedCriteria: parsed.weightedCriteria,
  constraints: parsed.constraints,
  reasoning: parsed.reasoning
};

return [{ json: { ...original, playerProfile } }];

const item = $input.item.json;
const p = item.playerProfile;
const errors = [];

if (!p || typeof p !== 'object') {
  errors.push('playerProfile fehlt oder ist kein Objekt.');
} else {
  if (!p.position) errors.push('playerProfile.position fehlt.');
  if (!p.role) errors.push('playerProfile.role fehlt.');
  if (!p.reasoning) errors.push('playerProfile.reasoning fehlt.');
  if (!Array.isArray(p.weightedCriteria) || p.weightedCriteria.length === 0) {
    errors.push('playerProfile.weightedCriteria fehlt oder ist leer.');
  } else if (p.weightedCriteria.some((c) => !c.criterion || typeof c.weight !== 'number')) {
    errors.push('playerProfile.weightedCriteria enthaelt einen Eintrag ohne criterion oder numerisches weight.');
  }
  if (!Array.isArray(p.constraints)) {
    errors.push('playerProfile.constraints fehlt oder ist kein Array.');
  } else if (p.constraints.some((c) => !c || !['age', 'marketValueMEUR'].includes(c.field) || !['max', 'min'].includes(c.operator) || typeof c.value !== 'number' || !Number.isFinite(c.value))) {
    // Constraints muessen strukturiert und filterbar sein (field/operator/value),
    // sonst koennen 'Player-Ranking-Anfrage vorbereiten' und der
    // Player-Ranking-Subworkflow sie nicht anwenden und sie waeren Dead Data.
    errors.push('playerProfile.constraints enthaelt einen Eintrag ohne gueltiges field/operator/numerisches value.');
  }

  // Generische Konsistenzpruefung (siehe n8n/README.md): das LLM darf keine
  // Position ausserhalb des durch teamDiagnosis.diagnosisCategory vorgegebenen
  // Pools waehlen. Die Parser-Schema-Validierung allein kann das nicht
  // garantieren, da 'position' dort nur als String (nicht als von der Diagnose
  // abhaengiges Enum) definiert ist - dieselbe Poolzuordnung wie in
  // "Spielerprofil: Positionspool ermitteln", hier erneut dupliziert, da
  // Code-Nodes keine gemeinsamen Hilfsfunktionen teilen koennen.
  if (p && p.position) {
    const DEFENSIVE_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld'];
    const ATTACKING_POSITIONS = ['Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];
    const ALL_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld', 'Zentrales Mittelfeld', 'Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];
    const diagnosisCategory = (item.teamDiagnosis && item.teamDiagnosis.diagnosisCategory) || 'no_data';
    const allowedPositions = diagnosisCategory === 'defensive'
      ? DEFENSIVE_POSITIONS
      : diagnosisCategory === 'offensive'
        ? ATTACKING_POSITIONS
        : ALL_POSITIONS;
    if (!allowedPositions.includes(p.position)) {
      errors.push(`playerProfile.position ('${p.position}') passt nicht zur Diagnosekategorie '${diagnosisCategory}' (erlaubt: ${allowedPositions.join(', ')}).`);
    }
  }
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Das Spielerprofil ist ungueltig und wird nicht fuer die Spielersuche verwendet.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const ranking = item.playerRanking;

// Ersetzt den bisherigen Dummy durch eine echte Auswertung des CSV-Analytics-
// Adapters (Player-Ranking abrufen, siehe n8n/README.md, Abschnitt
// "CSV-Analytics-Adapter"). Es werden keine Kandidaten erfunden: liefert der
// Adapter keine Ranglisten-Eintraege (z. B. weil der komplette Markt - alle
// Vereine ausser dem eigenen - fuer die Anfrage leer ist), bleibt shortlist
// leer und das nachfolgende Gate "Spielersuche gueltig?" greift.
if (!ranking || !ranking.dataAvailable || !Array.isArray(ranking.ranking) || ranking.ranking.length === 0) {
  const playerSearch = {
    simulated: false,
    dataAvailable: false,
    longlistSize: 0,
    shortlist: []
  };
  return [{ json: { ...item, playerSearch } }];
}

const pool = ranking.ranking;
const statFields = Object.keys(pool[0].stats).filter((f) => f !== 'age');
const poolAverage = {};
statFields.forEach((field) => {
  poolAverage[field] = pool.reduce((sum, p) => sum + p.stats[field], 0) / pool.length;
});

const shortlist = pool.slice(0, 5).map((candidate) => {
  const strengths = [];
  const weaknesses = [];
  statFields.forEach((field) => {
    const avg = poolAverage[field];
    if (candidate.stats[field] > avg) strengths.push(`${field}: ${candidate.stats[field]} (Pool-Schnitt ${avg.toFixed(2)})`);
    else if (candidate.stats[field] < avg) weaknesses.push(`${field}: ${candidate.stats[field]} (Pool-Schnitt ${avg.toFixed(2)})`);
  });

  return {
    name: candidate.name,
    score: candidate.score,
    strengths: strengths.length > 0 ? strengths : [`Score ${candidate.score} im CSV-Player-Ranking (${ranking.excludeClub ? 'ohne ' + ranking.excludeClub : ranking.club || 'alle Vereine'}${ranking.position ? ', ' + ranking.position : ''}).`],
    weaknesses: weaknesses.length > 0 ? weaknesses : ['Keine auffaelligen Schwaechen gegenueber dem betrachteten CSV-Pool.'],
    evidence: [`CSV-Analytics-Datenpunkt (Data Table football_scouting_raw): ${candidate.club}, ${candidate.position}, Alter ${candidate.age}, Rating ${candidate.stats.rating}, ${candidate.stats.goals} Tore, ${candidate.stats.assists} Vorlagen in ${candidate.stats.appearances} Einsaetzen.`]
  };
});

const playerSearch = {
  simulated: false,
  dataAvailable: true,
  longlistSize: ranking.poolSize,
  shortlist
};

return [{ json: { ...item, playerSearch } }];

const item = $input.item.json;
const s = item.playerSearch;
const errors = [];

// Ein vom Spielerprofil gefordertes Constraint (z. B. Alters-/Budgetlimit)
// kann im Player-Ranking-Subworkflow als 'ignoredConstraints' zurueckkommen,
// wenn das benoetigte Feld im Kandidatenpool nicht numerisch verfuegbar ist
// (siehe analytics-player-ranking-subworkflow.json). Ein still ignoriertes
// Constraint darf keine Empfehlung erreichen - das wuerde das
// Akzeptanzkriterium verletzen, dass Folgestufen die erzeugten Constraints
// tatsaechlich verwenden. Ein nicht anwendbares Constraint gilt hier deshalb
// als unzureichende Datengrundlage statt nur im Tool-Output (playerRanking)
// protokolliert zu werden.
const ignoredConstraints = (item.playerRanking && Array.isArray(item.playerRanking.ignoredConstraints))
  ? item.playerRanking.ignoredConstraints
  : [];
if (ignoredConstraints.length > 0) {
  errors.push('playerRanking.ignoredConstraints ist nicht leer - folgende Constraints aus dem Spielerprofil konnten im Player-Ranking nicht angewendet werden und wuerden sonst stillschweigend ignoriert: ' + JSON.stringify(ignoredConstraints) + '.');
}

// Dasselbe Problem gilt fuer vom Spielerprofil gewichtete Kriterien: nicht
// numerisch verfuegbare Kriterien landen im Ranking-Subworkflow in
// 'ignoredCriteria' und werden dort ggf. vollstaendig durch Default-Kriterien
// (goals/assists/xG) ersetzt, ohne dass 'dataAvailable' dadurch false wird.
// Damit wuerden die vom LLM erzeugten weightedCriteria die Folgestufe nicht
// mehr zuverlaessig steuern - analog zu ignoredConstraints gilt ein nicht
// verfuegbares Kriterium hier als unzureichende Datengrundlage.
const ignoredCriteria = (item.playerRanking && Array.isArray(item.playerRanking.ignoredCriteria))
  ? item.playerRanking.ignoredCriteria
  : [];
if (ignoredCriteria.length > 0) {
  errors.push('playerRanking.ignoredCriteria ist nicht leer - folgende vom Spielerprofil gewichteten Kriterien sind im Kandidatenpool nicht numerisch verfuegbar und wurden durch Default-Kriterien ersetzt: ' + JSON.stringify(ignoredCriteria) + '.');
}

// Wenn selbst der grobe Positionsgruppen-Match (DF/MF/FW/GK) fehlschlaegt,
// behaelt der Ranking-Subworkflow den kompletten ungefilterten Spielerpool
// (siehe analytics-player-ranking-subworkflow.json, posMatch()). Die vom
// Spielerprofil geforderte Position ginge damit vollstaendig verloren und ein
// Spieler einer voellig anderen Positionsgruppe koennte empfohlen werden -
// das gilt hier als unzureichende Datengrundlage.
if (item.playerRanking && item.playerRanking.positionFallbackApplied) {
  errors.push('playerRanking.positionFallbackApplied ist gesetzt - die angeforderte Position (' + (item.playerRanking.position || '?') + ') konnte im Kandidatenpool nicht einmal grob einer Positionsgruppe zugeordnet werden, der Pool wurde daher ungefiltert beibehalten.');
}

if (!s || typeof s !== 'object') {
  errors.push('playerSearch fehlt oder ist kein Objekt.');
} else {
  if (typeof s.longlistSize !== 'number' || s.longlistSize <= 0) errors.push('playerSearch.longlistSize fehlt oder ist ungueltig.');
  if (!Array.isArray(s.shortlist) || s.shortlist.length === 0) {
    errors.push('playerSearch.shortlist fehlt oder ist leer.');
  } else if (s.shortlist.length > 5) {
    errors.push('playerSearch.shortlist enthaelt mehr als fuenf Kandidaten.');
  } else if (s.shortlist.some((c) => !c.name || typeof c.score !== 'number' || !Array.isArray(c.strengths) || !Array.isArray(c.weaknesses) || !Array.isArray(c.evidence))) {
    errors.push('playerSearch.shortlist enthaelt einen Kandidaten ohne name, score, strengths, weaknesses oder evidence.');
  }
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Spielersuche ist ungueltig und wird nicht fuer die weitere Recherche verwendet.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const research = item.research;
const shortlistNames = (item.playerSearch && Array.isArray(item.playerSearch.shortlist))
  ? item.playerSearch.shortlist.map((c) => c.name)
  : [];
const errors = [];

if (!Array.isArray(research) || research.length === 0) {
  errors.push('research fehlt oder ist leer.');
} else {
  const researchedNames = research.map((r) => r.candidate).filter((name) => !!name);
  const uniqueResearchedNames = new Set(researchedNames);
  const shortlistSet = new Set(shortlistNames);

  if (researchedNames.length !== uniqueResearchedNames.size) {
    errors.push('research enthaelt denselben Kandidaten mehrfach.');
  }
  const missing = shortlistNames.filter((name) => !uniqueResearchedNames.has(name));
  if (missing.length > 0) {
    errors.push(`research deckt folgende Shortlist-Kandidaten nicht ab: ${missing.join(', ')}.`);
  }
  const unexpected = [...uniqueResearchedNames].filter((name) => !shortlistSet.has(name));
  if (unexpected.length > 0) {
    errors.push(`research enthaelt Kandidaten ausserhalb der Shortlist: ${unexpected.join(', ')}.`);
  }

  research.forEach((r, idx) => {
    if (!r.candidate || !shortlistSet.has(r.candidate)) errors.push(`research[${idx}].candidate fehlt oder ist nicht Teil der Shortlist.`);
    if (!r.club) errors.push(`research[${idx}].club (Verein) fehlt.`);
    if (!r.contract) errors.push(`research[${idx}].contract (Vertrag) fehlt.`);
    if (!r.marketValue) errors.push(`research[${idx}].marketValue (Marktwert) fehlt.`);
    if (!r.injuries) errors.push(`research[${idx}].injuries (Verletzungen) fehlt.`);
    if (!Array.isArray(r.news) || r.news.length === 0) errors.push(`research[${idx}].news (Meldungen) fehlt oder ist leer.`);
    if (!r.source) errors.push(`research[${idx}].source (Dummy-Quelle) fehlt.`);
    if (!r.timestamp) errors.push(`research[${idx}].timestamp (Zeitpunkt) fehlt.`);
    if (typeof r.confidence !== 'number') errors.push(`research[${idx}].confidence (Konfidenz) fehlt oder ist keine Zahl.`);
  });
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Recherche ist ungueltig und wird nicht fuer die Empfehlung verwendet.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;
const best = [...shortlist].sort((a, b) => b.score - a.score)[0];
const alternatives = shortlist.filter((c) => c.name !== best.name).map((c) => c.name);

const uncertainties = [
  'Empfehlung basiert vollstaendig auf simulierten Daten, keine echte Qlik-/Web-Recherche.'
];
// 'Spielersuche pruefen' blockt bereits den kompletten Fallback auf einen
// ungefilterten Pool (positionFallbackApplied). Ein grober Positionsgruppen-
// Match (DF/MF/FW/GK statt der exakt angeforderten Position, siehe
// analytics-player-ranking-subworkflow.json posMatch()) ist dagegen mit der
// FBref-Datengrundlage die Regel und wird deshalb nicht geblockt, aber hier
// explizit als Unsicherheit ausgewiesen statt stillschweigend uebernommen.
if (item.playerRanking && item.playerRanking.positionApproximationApplied) {
  uncertainties.push('Die angeforderte Position (' + (item.playerRanking.position || item.playerProfile.position) + ') konnte im Kandidatenpool nur grob auf eine Positionsgruppe (DF/MF/FW/GK) angenaehert werden, kein exakter Positionsabgleich.');
}

const recommendation = {
  simulated: true,
  candidate: best.name,
  alternatives,
  reasoning: `Simulierte Begruendung: ${best.name} hat in der simulierten Spielersuche den hoechsten Score (${best.score}).`,
  risks: [
    'Simuliertes Risiko, das bei einer echten Analyse zu pruefen waere',
    'Simuliertes Risiko aus der noch unvollstaendigen echten Recherche'
  ],
  uncertainties,
  nextStep: 'Naechster Schritt: die Dummy-Stufen schrittweise durch die echte AI-, Qlik- und Web-Anbindung ersetzen.'
};

return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const errors = [];

const d = item.teamDiagnosis;
if (!d || !d.mainProblem) errors.push('teamDiagnosis.mainProblem fehlt in der finalen Pruefung.');

const p = item.playerProfile;
if (!p || !p.position || !p.role) errors.push('playerProfile.position/role fehlt in der finalen Pruefung.');

const s = item.playerSearch;
const shortlistNames = (s && Array.isArray(s.shortlist)) ? s.shortlist.map((c) => c.name) : [];
if (!s || shortlistNames.length === 0) errors.push('playerSearch.shortlist fehlt in der finalen Pruefung.');

const research = item.research;
if (!Array.isArray(research) || research.length === 0) errors.push('research fehlt in der finalen Pruefung.');

const r = item.recommendation;
if (!r || !r.candidate) {
  errors.push('recommendation.candidate fehlt in der finalen Pruefung.');
} else if (!shortlistNames.includes(r.candidate)) {
  errors.push('recommendation.candidate stammt nicht aus der validierten Shortlist.');
}
if (!r || !Array.isArray(r.alternatives)) errors.push('recommendation.alternatives fehlt in der finalen Pruefung.');
if (!r || !r.reasoning) errors.push('recommendation.reasoning fehlt in der finalen Pruefung.');
if (!r || !Array.isArray(r.risks) || r.risks.length === 0) errors.push('recommendation.risks fehlt oder ist leer in der finalen Pruefung.');
if (!r || !Array.isArray(r.uncertainties) || r.uncertainties.length === 0) errors.push('recommendation.uncertainties fehlt oder ist leer in der finalen Pruefung.');
if (!r || !r.nextStep) errors.push('recommendation.nextStep fehlt in der finalen Pruefung.');

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die finale Validierung ist fehlgeschlagen, es wird keine fachliche Empfehlung angezeigt.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const d = item.teamDiagnosis;
const p = item.playerProfile;
const s = item.playerSearch;
const research = item.research || [];
const r = item.recommendation;

const section = (title, lines) => `— ${title} —\n${lines.join('\n')}`;

const researchLines = research.map((x) => `${x.candidate}: ${x.club}, ${x.contract}, ${x.marketValue}, ${x.injuries} (Quelle: ${x.source}, ${x.timestamp}, Konfidenz ${x.confidence})`);

const empfehlungLines = [`Bevorzugter Kandidat: ${r.candidate}`, `Begruendung: ${r.reasoning}`, `Naechster Schritt: ${r.nextStep}`];
if (r.candidateProfile) {
  const cp = r.candidateProfile;
  empfehlungLines.push(`CSV-Analytics-Profil (Data Table football_scouting_raw): ${cp.club}, ${cp.position}, Alter ${cp.age}, Rating ${cp.rating}, ${cp.goals} Tore, ${cp.assists} Vorlagen in ${cp.appearances} Einsaetzen.`);
}

const formattedResult = [
  `Verein: ${item.club}`,
  `Auftrag: ${item.objective}`,
  item.additionalContext ? `Zusaetzlicher Kontext: ${item.additionalContext}` : null,
  '',
  '⚠ Hinweis: Teamdiagnose und Spielerprofil (Bedarfsermittlung) werden von einem lokalen LLM auf Basis des CSV-Analytics-Adapters (Referenzdaten, siehe n8n/data/README.md) interpretiert, nicht simuliert. Spielersuche greift ebenfalls real auf diese Daten zu. Nur Recherche ist weiterhin ein vollstaendig simuliertes Dummy-Ergebnis, da hierfuer noch keine reale Implementierung existiert.',
  '',
  section('Teamdiagnose', [`Hauptproblem: ${d.mainProblem}`, ...d.hypotheses.map((h) => `Hypothese: ${h}`)]),
  '',
  section('Spielerprofil', [`Position: ${p.position}`, `Rolle: ${p.role}`, `Begruendung: ${p.reasoning}`]),
  '',
  section('Spielersuche', [`Longlist-Groesse: ${s.longlistSize}`, ...s.shortlist.map((c) => `${c.name} (Score ${c.score})`)]),
  '',
  section('Recherche', researchLines),
  '',
  section('Empfehlung', empfehlungLines)
].filter((line) => line !== null).join('\n');

return [{ json: { ...item, formattedResult } }];

const item = $input.item.json;
const p = item.playerProfile;

return [{
  json: {
    ...item,
    rankingExcludeClub: item.club,
    position: p.position,
    criteria: p.weightedCriteria,
    constraints: p.constraints || [],
    limit: 5
  }
}];

const item = $input.item.json;
const lookup = item.playerProfileLookup;

const recommendation = {
  ...item.recommendation,
  candidateProfile: (lookup && lookup.found) ? lookup.profile : null
};

return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const d = item.teamDiagnosis;

// diagnosisCategory 'no_data' bedeutet: es gibt keine belastbare
// Teamdiagnose, aus der ein Spielerprofil abgeleitet werden koennte (siehe
// 'Teamdiagnose (keine Daten) erzeugen'). Ohne diesen Stopp wuerde
// 'Spielerprofil: Positionspool ermitteln' auf ALL_POSITIONS zurueckfallen
// und die Pipeline bis zur Empfehlung weiterlaufen, obwohl keine Evidenz
// vorliegt - das widerspricht der Story-Vorgabe, bei unzureichender Evidenz
// Unsicherheit auszuweisen bzw. weitere Analytics anzufordern statt sichere
// Folgeschluesse zu erfinden.
const valid = !!d && d.diagnosisCategory !== 'no_data';

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : `Fuer '${item.club}' liegen keine ausreichenden Analytics-Daten fuer eine Teamdiagnose vor. Eine Bedarfsermittlung (Spielerprofil) und Spielersuche werden deshalb nicht durchgefuehrt, statt auf einen beliebigen Positionspool zurueckzufallen. Bitte weitere Analytics-Daten fuer diesen Verein bereitstellen.\n\n${d && d.mainProblem ? d.mainProblem : ''}`
  }
}];

const MAX_REVIEW_ROUNDS = 3;
const item = $input.item.json;
const priorBrief = item.scoutingBrief;
const feedbackHistory = Array.isArray(priorBrief && priorBrief.feedbackHistory)
  ? [...priorBrief.feedbackHistory]
  : [];

// Nach einer 'Request Changes'-Runde hat 'Spielerprofil LLM' das Profil
// bereits unter Beruecksichtigung von reviewFeedback neu erzeugt (siehe
// dortiger Prompt); hier wird das Feedback der vorherigen Runde in die
// Historie uebernommen, bevor das ueberarbeitete Brief erneut vorgelegt wird.
if (item.reviewDecision === 'Request Changes' && priorBrief) {
  feedbackHistory.push({ round: priorBrief.reviewRound, feedback: item.reviewFeedback || '' });
}

const teamDiagnosis = item.teamDiagnosis || {};
const playerProfile = item.playerProfile || {};

const scoutingBrief = {
  problem: teamDiagnosis.mainProblem,
  targetPosition: playerProfile.position,
  role: playerProfile.role,
  reasoning: playerProfile.reasoning,
  weightedCriteria: playerProfile.weightedCriteria,
  constraints: playerProfile.constraints,
  uncertainties: Array.isArray(teamDiagnosis.uncertainties) ? teamDiagnosis.uncertainties : [],
  reviewRound: feedbackHistory.length + 1,
  maxReviewRounds: MAX_REVIEW_ROUNDS,
  feedbackHistory
};

return [{ json: { ...item, scoutingBrief } }];

const item = $input.item.json;
const b = item.scoutingBrief;
const errors = [];

if (!b || typeof b !== 'object') {
  errors.push('scoutingBrief fehlt oder ist kein Objekt.');
} else {
  if (!b.problem) errors.push('scoutingBrief.problem fehlt.');
  if (!b.targetPosition) errors.push('scoutingBrief.targetPosition fehlt.');
  if (!b.role) errors.push('scoutingBrief.role fehlt.');
  if (!b.reasoning) errors.push('scoutingBrief.reasoning fehlt.');
  if (!Array.isArray(b.weightedCriteria) || b.weightedCriteria.length === 0) {
    errors.push('scoutingBrief.weightedCriteria fehlt oder ist leer.');
  }
  if (!Array.isArray(b.constraints)) errors.push('scoutingBrief.constraints fehlt oder ist kein Array.');
  if (!Array.isArray(b.uncertainties)) errors.push('scoutingBrief.uncertainties fehlt oder ist kein Array.');
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Das Scouting Brief ist ungueltig und wird nicht zur Freigabe vorgelegt.\n\n' + errors.join('\n')
  }
}];

